import React from "react";
import Navbar from "../components/navbar";
import VideoUpload from "../components/videoUpload";

const Home = () => {
    const [videos, setVideos] = useState([]);

    // Fetch uploaded videos from backend
    useEffect(() => {
        axios.get("http://localhost:5000/api/videos") // Fetch list of video IDs
            .then(response => setVideos(response.data))
            .catch(error => console.error("Error fetching videos:", error));
    }, []);

    return (
        <div>
            <Navbar />
            <VideoUpload />
            <h1 className="p-4">Welcome to YouTube Clone</h1>
            
            <div className="video-list">
                {videos.length === 0 ? (
                    <p>No videos available</p>
                ) : (
                    videos.map((video) => (
                        <div key={video.id} className="video-container">
                            <h3>Video ID: {video.id}</h3>
                            <video width="400" controls>
                                <source src={`http://localhost:3000/api/videos/stream/${video.id}`} type="video/mp4" />
                                Your browser does not support the video tag.
                            </video>
                        </div>
                    ))
                )}
            </div>
        </div>
    );
};

export default Home;
